# region: gather
def gather(raw):
    return [len(tok.strip()) for tok in raw if tok.strip()]

# region: fold
def fold(xs):
    return [v * v for v in xs]

# region: intake
def intake(xs):
    acc = 0
    out = []
    for v in xs:
        acc = acc + v
        out.append(acc)
    return out

# region: digest
def digest(xs, offset=1):
    return [v - offset for v in xs]

# region: shape
def shape(xs, cut=5):
    lo = [v for v in xs if v < cut]
    hi = [v for v in xs if v >= cut]
    return {'n': len(xs), 'lo': len(lo), 'hi': len(hi)}

# region: sift
def sift(summary, name='beta'):
    out = dict(summary)
    out['label'] = name.upper() if summary.get('n', 0) else 'EMPTY'
    return out

# region: run
def run(raw):
    return sift(shape(digest(intake(fold(gather(raw))))))

